//! usbport.resource's functions: who holds each of the chip's USB ports,
//! and which controller it is given to - on the ESP32-S3 the console's
//! USB-Serial-JTAG port or the USB OTG controller, which share the one.
//! A resource: no Open or Close, its first function in the first slot.
//! The base comes from OpenResource("usbport.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/usbport_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const usbport = @import("../resources/usbport.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "usbport.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const OwnUSBPort = libraries.lvo(0);
    pub const ReleaseUSBPort = libraries.lvo(1);
    pub const USBPortOwner = libraries.lvo(2);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const OwnUSBPort = *const fn (*UsbPortBase, *usbport.USBPortHandle) callconv(.c) bool;
    pub const ReleaseUSBPort = *const fn (*UsbPortBase, *usbport.USBPortHandle, u32) callconv(.c) void;
    pub const USBPortOwner = *const fn (*UsbPortBase, u32) callconv(.c) ?[*:0]const u8;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const UsbPortBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *UsbPortBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// Bid for the port of `handle`'s controller: true if it holds it now,
    /// else it is told by its signals when it does.
    pub fn OwnUSBPort(self: *UsbPortBase, handle: *usbport.USBPortHandle) bool {
        return libraries.call(self, LVO.OwnUSBPort, Fn.OwnUSBPort, .{handle});
    }

    /// Let go of the port, or of the bid; with USBPORTF_REMOVE leave the
    /// bidders too.
    pub fn ReleaseUSBPort(self: *UsbPortBase, handle: *usbport.USBPortHandle, flags: u32) void {
        return libraries.call(self, LVO.ReleaseUSBPort, Fn.ReleaseUSBPort, .{ handle, flags });
    }

    /// Who holds `port`, or null if nobody does.
    pub fn USBPortOwner(self: *UsbPortBase, port: u32) ?[*:0]const u8 {
        return libraries.call(self, LVO.USBPortOwner, Fn.USBPortOwner, .{port});
    }
};
